const BASE=(()=>{try{const el=[...document.scripts].find(x=>/(^|\/)app\.js(?:\?|$)/.test(x.getAttribute('src')||''));if(!el)return'';const dir=new URL(el.getAttribute('src'),location.href).pathname.replace(/\/assets\/js\/app\.js$/,'').replace(/\/app\.js$/,'');return dir==='/'?'':dir}catch(e){return''}})();const url=p=>typeof p==='string'&&p.charAt(0)==='/'?BASE+p:p;const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const root=$('#root');let route=location.pathname.replace(/\/$/,'')||'/';if(BASE&&(route===BASE||route.startsWith(BASE+'/')))route=route.slice(BASE.length)||'/';const aliases={'/prihlaseni':'/login','/registrace':'/register','/herni-mody':'/game-modes','/funkce':'/features'};route=aliases[route]||route;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let profile={first:'Alex',last:'Novák',username:'alex180',email:'alex@example.cz',avatar:'🎯'};let hasDemoProfile=false;try{const raw=sessionStorage.getItem('dartiqo-demo-profile');if(raw){hasDemoProfile=true;profile={...profile,...JSON.parse(raw)}}}catch{}const currentUser=(()=>{try{return JSON.parse($('#current-user')?.textContent||'null')}catch{return null}})();if(currentUser){profile={...profile,...currentUser};hasDemoProfile=true}let csrfToken=$('meta[name="csrf-token"]')?.content||'';async function api(path,data,method='POST'){const res=await fetch(url(path),{method,credentials:'same-origin',headers:method==='GET'?{'Accept':'application/json'}:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-Token':csrfToken},body:method==='GET'?undefined:JSON.stringify(data||{})});let body={};try{body=await res.json()}catch{}if(body.csrf)csrfToken=body.csrf;return{status:res.status,...body}}function toast(s){$('#toast').textContent=s;$('#toast').classList.add('toast-visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('toast-visible'),4000)}function modal(title,body){const d=document.createElement('div');d.className='fixed inset-0 z-[80] flex items-center justify-center bg-black/60 p-6 backdrop-blur-md';d.innerHTML=`<section class="w-full max-w-md rounded-3xl bg-surface p-8" role="dialog" aria-modal="true" aria-label="${escapeHtml(title)}"><button class="flex size-9 items-center justify-center rounded-full border border-line bg-transparent text-ink home:border-white/15 home:text-[#eee] max-md:home:size-8 controls:border-line! controls:text-ink! ml-auto" data-close aria-label="Zavřít">×</button><h3 class="my-4">${escapeHtml(title)}</h3><p class="text-sm">${body}</p></section>`;document.body.append(d);$('[data-close]',d).onclick=()=>d.remove();d.onclick=e=>{if(e.target===d)d.remove()};d.onkeydown=e=>{if(e.key==='Escape')d.remove()};$('[data-close]',d).focus()}
