function games(){return intro('HERNÍ MÓDY','Jedna vášeň.<br><span class="text-accent">Osm způsobů hry.</span>','Od klasické 501 po vlastní kariéru. Vyber režim a prozkoumej jeho nastavení.')+`<section class="mx-auto w-full max-w-7xl px-6 md:px-12 pb-24">${gameCards()}</section>`+cta()}
function modeDetail(id){const g=gameData.find(g=>g[0]===id)||gameData[0];return intro(g[4],g[1]+'.<br><span class="text-accent">Tvoje další výzva.</span>',g[2])+`<section class="mx-auto w-full max-w-7xl px-6 md:px-12 pb-24 grid lg:grid-cols-2 gap-6"><div class="rounded-3xl border border-line bg-surface p-6 md:p-8"><span class="mb-3 inline-block text-[9px] tracking-widest text-accent uppercase">INTERAKTIVNÍ NASTAVENÍ · UKÁZKA</span><h3>Nastav si vlastní tempo</h3><label for="start-score">Výchozí skóre</label><select id="start-score"><option>301</option><option selected>501</option><option>701</option></select><label for="finish">Zakončení</label><select id="finish"><option>Double out</option><option>Straight out</option><option>Master out</option></select><label for="difficulty">${id==='dartbot'?'Úroveň bota':'Délka zápasu'}</label><select id="difficulty">${(id==='dartbot'?['Začátečník','Pokročilý','Expert']:['Na 1 vítězný leg','Na 3 vítězné legy','Na 5 vítězných legů']).map(v=>`<option>${v}</option>`).join('')}</select><button class="inline-flex items-center justify-center gap-5 rounded-full bg-accent px-6 py-3.5 text-xs font-bold text-black shadow-none transition-all duration-200 hover:-translate-y-[3px] hover:shadow-[0_8px_30px_#faff0020] mt-6" data-demo="Nastavení je připravené. Spouštění plné hry není součástí designového dema.">Připravit zápas ↗</button></div><div class="rounded-3xl border border-line bg-surface p-6 md:p-8 flex flex-col justify-center text-center"><span class="text-[10px] font-bold uppercase tracking-[.22em] text-muted">${g[1]} / NÁHLED</span><div class="text-8xl font-display font-bold text-accent my-8" id="config-preview">${id==='cricket'?'20 · 19':'501'}</div><span id="config-caption" class="rounded-full bg-surface-2 px-3 py-1.5 text-[9px] uppercase tracking-widest text-muted mx-auto">Double out</span><p class="text-xs mt-6">Alex vs ${id==='dartbot'?'DartBot':'Sam'} · Ukázkoví hráči</p></div><article class="rounded-3xl border border-line bg-surface p-6 md:p-8 lg:col-span-2"><h3>Jak se hraje</h3><div class="grid md:grid-cols-3 gap-7 mt-5">${(id==='cricket'?['Uzavírej čísla 15 až 20 a bull třemi zásahy.','Na čísle, které soupeř ještě neuzavřel, můžeš bodovat.','Vyhraješ po uzavření všech cílů, pokud nemáš méně bodů.']:['V jednom tahu máš tři šipky. Každý zásah ovlivní tvoje skóre.','V X01 odečítáš body a musíš dosáhnout přesně nuly.','Způsob zakončení určuje nastavení. Double out vyžaduje double.']).map((v,i)=>`<div><span class="text-accent text-xs">0${i+1}</span><p class="text-sm mt-3">${v}</p></div>`).join('')}</div><p class="mt-5 text-[10px] leading-relaxed text-muted">Konfigurátor ukazuje podobu nastavení. ${g[1]} je připravovaný režim; skutečný zápas se zde nespouští.</p></article></section>`}
const trainings=[['Around the Clock','Přesnost','Postupně zasáhni čísla 1 až 20.'],["Bob’s 27",'Doubly','Začni na 27 bodech a projdi doubly.'],['121 Checkout','Zavírání','Zkus zavřít 121 na devět šipek.'],['Shanghai','Přesnost','Single, double, triple jednoho čísla.'],['Halve-It','Přesnost','Plň cíle, jinak se skóre půlí.'],['Doubles Training','Doubly','Soustřeď se na rozhodující kruh.'],['Scoring Practice','Skórování','Najdi konzistentní rytmus.'],['Checkout Practice','Zavírání','Trénuj cestu k poslednímu doublu.'],['Accuracy Challenge','Přesnost','Méně rozptylu, více jistoty.'],['Pressure Training','Zavírání','Tři šipky. Jeden pokus.']];function trainingCards(cat='Vše'){return trainings.filter(t=>cat==='Vše'||t[1]===cat).map((t,i)=>`<button class="rounded-3xl border border-line bg-surface p-6 md:p-8 text-left hover:border-accent" data-training="${escapeHtml(t[0])}"><span class="text-[10px] font-bold uppercase tracking-[.22em] text-muted">${t[1]}</span><div class="text-accent text-4xl my-5">${['◎','27','121','Ⅲ'][i%4]}</div><h3>${t[0]}</h3><p class="text-xs mt-3">${t[2]}</p><span class="text-xs inline-block mt-5">Detail tréninku ↗</span></button>`).join('')}
