const dashNode=$('#dash-data');
if(dashNode){
  const dash=JSON.parse(dashNode.textContent);
  useChartTheme();
  const minutes=m=>{const h=Math.floor(m/60),min=m%60;return h?h+' h '+String(min).padStart(2,'0')+' min':min+' min'};
  let period=dash.default,result='all',aimPick=null,heatZoom=1,currentBoard=null,trendKind='bar';
  const charts={};
  const mountChart=(key,node,config)=>{if(!node||typeof Chart==='undefined')return;charts[key]?.destroy();charts[key]=new Chart(node,config)};
  const dayNames=['Ne','Po','Út','St','Čt','Pá','So'];
  const trendLabels=n=>Array.from({length:n},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(n-1-i));if(n===1)return 'Dnes';if(n<=7)return dayNames[d.getDay()];return d.getDate()+'. '+(d.getMonth()+1)+'.'});
  const paintChart=values=>{
    const canvas=$('#stat-chart');if(!canvas)return;
    const list=(values||[]).map(v=>v==null?null:Number(v));
    if(!list.some(v=>v!==null)){charts.trend?.destroy();charts.trend=null;return}
    const labels=trendLabels(list.length);
    const avg=v=>'Průměr '+String(v).replace('.',',');
    const yBase={grid:{color:'rgba(255,255,255,.06)'},ticks:{color:'#71717a',font:{size:10},maxTicksLimit:5},border:{display:false}};
    const scales={x:{grid:{display:false},ticks:{color:'#71717a',font:{size:10},maxRotation:0,autoSkip:true,maxTicksLimit:list.length>10?8:list.length},border:{display:false}},y:trendKind==='bar'?{...yBase,beginAtZero:true,grace:'8%'}:{...yBase,grace:'16%'}};
    const tooltip={displayColors:false,callbacks:{label:c=>avg(c.parsed.y)}};
    const fill=ctx=>{const box=ctx.chart.chartArea;if(!box)return 'rgba(74,222,128,.28)';const g=ctx.chart.ctx.createLinearGradient(0,box.top,0,box.bottom);g.addColorStop(0,'rgba(74,222,128,.45)');g.addColorStop(1,'rgba(74,222,128,0)');return g};
    if(trendKind==='bar'){
      mountChart('trend',canvas,{type:'bar',data:{labels,datasets:[{data:list,backgroundColor:list.map((_,i)=>i===list.length-1?'#4ade80':'rgba(74,222,128,.38)'),hoverBackgroundColor:'#86efac',borderRadius:list.length>20?4:8,borderSkipped:false,maxBarThickness:42}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip},scales}});
      return;
    }
    mountChart('trend',canvas,{type:'line',data:{labels,datasets:[{data:list,borderColor:'#4ade80',backgroundColor:trendKind==='area'?fill:'transparent',fill:trendKind==='area',tension:.35,borderWidth:2.5,pointRadius:list.length>16?0:3.5,pointHoverRadius:5,pointHitRadius:10,pointBackgroundColor:'#18181b',pointBorderColor:'#4ade80',pointBorderWidth:2}]},options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{legend:{display:false},tooltip},scales}});
  };
  const paintBands=bands=>{
    const rows=bands||[],total=rows.reduce((s,b)=>s+(+b[1]||0),0)||1;
    if($('#score-total'))$('#score-total').textContent=total+' kol';
    if($('#score-grid'))$('#score-grid').innerHTML=rows.map(b=>`<div class="tile px-2 py-2 text-center"><strong class="num block text-lg">${b[1]}</strong><span class="mt-0.5 inline-flex items-center gap-1 text-[10px] text-zinc-400"><i class="inline-block size-1.5 rounded-full" style="background:${b[2]}"></i>${escapeHtml(b[0])}</span></div>`).join('');
    mountChart('score',$('#score-chart'),{type:'bar',data:{labels:rows.map(b=>b[0]),datasets:[{data:rows.map(b=>+b[1]||0),backgroundColor:rows.map(b=>b[2]),borderRadius:6,borderSkipped:false,barThickness:14}]},options:{indexAxis:'y',responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{displayColors:false,callbacks:{label:c=>{const n=+c.raw||0;return n+' kol · '+Math.round(n/total*100)+' %'}}}},scales:{x:{beginAtZero:true,grid:{color:'rgba(255,255,255,.06)'},ticks:{color:'#71717a',font:{size:10},precision:0},border:{display:false}},y:{grid:{display:false},ticks:{color:'#e4e4e7',font:{size:11}},border:{display:false}}}}});
  };
  const paintFocus=p=>{
    const c=p.closing||{rate:0,hits:0,attempts:0,best:['—',0,1],worst:['—',0,1],doubles:[],ranges:[],count:0,highest:'—',average:'—'};
    const w=p.wins||{rate:0,won:0,played:0,form:[]};
    if($('#co-rate'))$('#co-rate').textContent=c.rate+' %';
    if($('#co-ratio'))$('#co-ratio').textContent=c.hits+' / '+c.attempts;
    if($('#co-bar'))$('#co-bar').style.width=c.rate+'%';
    const extreme=(title,row,kind)=>{
      const rate=row[2]?Math.round(row[1]/row[2]*100):0;
      const box=kind==='best'?'bg-emerald-400/[.07] ring-emerald-400/25':'bg-rose-400/[.07] ring-rose-400/25';
      const ink=kind==='best'?'text-emerald-300':'text-rose-300';
      return `<div class="rounded-2xl p-4 ring-1 ring-inset ${box}"><span class="text-[10px] font-semibold uppercase tracking-widest ${ink}">${title}</span><div class="mt-1 flex items-end justify-between gap-2"><strong class="num text-2xl">${escapeHtml(row[0])}</strong><b class="num ${ink}">${rate} %</b></div><small class="text-xs text-zinc-500">${row[1]} z ${row[2]} pokusů</small></div>`;
    };
    if($('#co-extremes'))$('#co-extremes').innerHTML=extreme('Nejlepší double',c.best,'best')+extreme('Nejslabší double',c.worst,'worst');
    const doubles=c.doubles||[];
    if($('#co-list'))$('#co-list').innerHTML=doubles.map(r=>{
      const rate=r[2]?Math.round(r[1]/r[2]*100):0;
      const [fill,ink]=r[0]===c.best[0]?['#4ade80','text-emerald-300']:r[0]===c.worst[0]?['#fb7185','text-rose-300']:['#faff00','text-zinc-100'];
      return `<div class="tile flex items-center gap-3 px-3 py-2"><strong class="num w-9 shrink-0 text-sm">${escapeHtml(r[0])}</strong><div class="meter flex-1"><i style="width:${rate}%;background:${fill}"></i></div><small class="num w-11 shrink-0 text-right text-[11px] text-zinc-500">${r[1]}/${r[2]}</small><b class="num w-12 shrink-0 text-right text-sm whitespace-nowrap ${ink}">${rate} %</b></div>`;
    }).join('');
    if($('#co-ranges'))$('#co-ranges').innerHTML=(c.ranges||[]).map(r=>`<div class="tile px-2 py-2 text-center"><strong class="num block text-lg">${r[1]}</strong><span class="mt-0.5 block text-[10px] text-zinc-400">${escapeHtml(r[0])}</span></div>`).join('');
    if($('#co-meta'))$('#co-meta').textContent=`${c.count} zavření · nejvyšší ${c.highest} · Ø ${c.average}`;
    if($('#co-total'))$('#co-total').textContent=c.attempts+' pokusů';
    if($('#win-rate'))$('#win-rate').textContent=w.rate+' %';
    if($('#win-ratio'))$('#win-ratio').textContent=`${w.won} z ${w.played} zápasů`;
    if($('#win-bar'))$('#win-bar').style.width=w.rate+'%';
    if($('#win-won'))$('#win-won').textContent=w.won;
    if($('#win-lost'))$('#win-lost').textContent=Math.max(0,w.played-w.won);
    if($('#win-played'))$('#win-played').textContent=w.played;
    if($('#hero-win'))$('#hero-win').textContent=w.rate+' %';
    if($('#hero-co'))$('#hero-co').textContent=c.rate+' %';
    if($('#hero-played'))$('#hero-played').textContent=w.played;
    if($('#win-form'))$('#win-form').innerHTML=(w.form||[]).map(on=>`<i class="grid size-8 place-items-center rounded-lg text-[11px] font-bold not-italic ${on?'bg-emerald-400/90 text-black':'bg-white/[.06] text-zinc-500'}">${on?'V':'P'}</i>`).join('');
  };
  const paintShares=(board,misses)=>DartBoard.paintShares($('#map-shares'),$('#map-fields'),board,misses);
  const paintAim=board=>{aimPick=DartBoard.paintAim({chart:$('#aim-chart'),detail:$('#aim-detail'),min:$('#aim-min'),max:$('#aim-max'),bull:$('#aim-bull')},board,aimPick)};
  const paintHeat=(board,seedKey,misses)=>DartBoard.paintHeat($('#heat-board'),board,seedKey,$('#heat-stats'),misses);
  const paintPeriod=name=>{
    period=name;
    const p=dash.periods[name];
    if(!p)return;
    $('#stat-average').textContent=p.average;
    $('#stat-delta').textContent=p.delta;
    $('#stat-delta-note').textContent=p.deltaNote;
    paintChart(p.chart);
    paintFocus(p);
    paintBands(p.bands);
    $('#kpi-grid').innerHTML=p.kpis.map(([label,value,detail])=>`<article class="panel p-4! sm:p-5!"><span class="eyebrow tracking-[.12em]">${escapeHtml(label)}</span><strong class="num mt-3 block text-3xl leading-none">${escapeHtml(value)}</strong><small class="mt-2 block text-xs text-zinc-500">${escapeHtml(detail)}</small></article>`).join('');
    currentBoard=p.board||null;
    aimPick=null;
    if(currentBoard){paintAim(currentBoard);paintHeat(currentBoard,name,p.misses||0);paintShares(currentBoard,p.misses||0)}
    const timeSum=p.time.reduce((s,t)=>s+t[1],0);
    const share=m=>timeSum?Math.round(m/timeSum*100):0;
    const timeTop=p.time.reduce((top,t)=>!top||t[1]>top[1]?t:top,null);
    $('#time-total').textContent=minutes(timeSum);
    $('#time-daily').textContent=minutes(Math.round(timeSum/Math.max(1,(p.chart||[]).length)));
    mountChart('time',$('#time-chart'),{type:'doughnut',data:{labels:p.time.map(t=>t[0]),datasets:[{data:p.time.map(t=>t[1]),backgroundColor:p.time.map(t=>t[2]),borderWidth:0,spacing:4,borderRadius:8,hoverOffset:6}]},options:{responsive:true,maintainAspectRatio:false,cutout:'76%',layout:{padding:6},plugins:{legend:{display:false},tooltip:{displayColors:false,callbacks:{label:c=>c.label+' · '+minutes(+c.raw||0)+' · '+share(+c.raw||0)+' %'}}}}});
    $('#time-legend').innerHTML=p.time.map(t=>`<div class="tile px-4 py-3"><div class="flex items-center justify-between gap-3 text-sm"><span class="flex items-center gap-2.5 text-zinc-300"><i class="size-2.5 rounded-full" style="background:${t[2]}"></i>${escapeHtml(t[0])}</span><span class="flex items-baseline gap-3"><b class="num text-white">${minutes(t[1])}</b><small class="num w-9 text-right text-xs text-zinc-500">${share(t[1])} %</small></span></div><div class="meter mt-2.5"><i style="width:${share(t[1])}%;background:${t[2]}"></i></div></div>`).join('');
    if(timeTop)$('#time-note').innerHTML=`Nejvíc času trávíš <b class="text-zinc-200">${escapeHtml(timeTop[0].toLowerCase())}</b> – ${share(timeTop[1])} % z celku.`;
    $$('[data-period]').forEach(b=>b.classList.toggle('active',b.dataset.period===name));
    paintGames();
  };
  const paintGames=()=>{
    const maxDays=dash.maxDays[period]??9999;
    let shown=0;
    $$('[data-game]').forEach(row=>{
      const days=+row.dataset.days;
      const dayOk=period==='Dnes'?days===0:days<=maxDays;
      const resOk=result==='all'||row.dataset.result===result;
      const ok=dayOk&&resOk;
      row.hidden=!ok;
      if(ok)shown++;
    });
    const empty=$('#games-empty');
    if(empty)empty.hidden=shown!==0;
  };
  const pickAim=el=>{if(!el||!currentBoard)return;aimPick=+el.dataset.aim;paintAim(currentBoard)};
  $('#aim-chart')?.addEventListener('click',e=>pickAim(e.target.closest('[data-aim]')));
  $('#aim-chart')?.addEventListener('keydown',e=>{if(e.key!=='Enter'&&e.key!==' ')return;const el=e.target.closest('[data-aim]');if(!el)return;e.preventDefault();pickAim(el)});
  $$('[data-heat-zoom]').forEach(b=>b.onclick=()=>{heatZoom=Math.min(2.3,Math.max(1,+((heatZoom+(+b.dataset.heatZoom)).toFixed(2))));const size=500/heatZoom,o=(500-size)/2;$('#heat-board')?.setAttribute('viewBox',`${o} ${o} ${size} ${size}`)});
  $$('[data-period]').forEach(b=>b.onclick=()=>paintPeriod(b.dataset.period));
  $$('[data-trend]').forEach(b=>b.onclick=()=>{trendKind=b.dataset.trend;$$('[data-trend]').forEach(x=>{const on=x===b;x.classList.toggle('active',on);x.setAttribute('aria-pressed',on?'true':'false')});const p=dash.periods[period];if(p)paintChart(p.chart)});
  $$('[data-result]').forEach(b=>b.onclick=()=>{result=b.dataset.result;$$('[data-result]').forEach(x=>x.classList.toggle('active',x===b));paintGames()});
  paintPeriod(dash.default);
}

const gamesPage=$('#games-page');
if(gamesPage){
  let result='all',query='';
  const paint=()=>{
    const q=query.trim().toLowerCase();
    let shown=0;
    $$('[data-game]',gamesPage).forEach(row=>{
      const ok=(result==='all'||row.dataset.result===result)&&(!q||(row.dataset.search||'').includes(q));
      row.hidden=!ok;
      if(ok)shown++;
    });
    const empty=$('#games-empty');
    if(empty)empty.hidden=shown!==0;
    const count=$('#games-count');
    if(count)count.textContent=shown===1?'1 hra':shown>=2&&shown<=4?shown+' hry':shown+' her';
  };
  $$('[data-result]',gamesPage).forEach(b=>b.onclick=()=>{result=b.dataset.result;$$('[data-result]',gamesPage).forEach(x=>x.classList.toggle('active',x===b));paint()});
  const input=$('#games-query');
  if(input)input.oninput=()=>{query=input.value;paint()};
}

const matchNode=$('#match-data');
if(matchNode&&typeof DartBoard!=='undefined'){
  const match=JSON.parse(matchNode.textContent);
  useChartTheme();
  const board=match.board||{segments:{},bull:[0,0]};
  let aimPick=null,heatZoom=1;
  const aimEls=()=>({chart:$('#aim-chart'),detail:$('#aim-detail'),min:$('#aim-min'),max:$('#aim-max'),bull:$('#aim-bull')});
  const paintAim=()=>{aimPick=DartBoard.paintAim(aimEls(),board,aimPick)};
  paintAim();
  DartBoard.paintHeat($('#heat-board'),board,match.id||'match',$('#heat-stats'),match.misses||0);
  DartBoard.paintShares($('#map-shares'),$('#map-fields'),board,match.misses||0);
  const bands=match.bands||[];
  const total=bands.reduce((s,b)=>s+(+b[1]||0),0);
  if($('#score-total'))$('#score-total').textContent=total+' '+(match.unit||'kol');
  if($('#score-grid'))$('#score-grid').innerHTML=bands.map(b=>`<div class="tile px-2 py-2 text-center"><strong class="num block text-lg">${b[1]}</strong><span class="mt-0.5 inline-flex items-center gap-1 text-[10px] text-zinc-400"><i class="inline-block size-1.5 rounded-full" style="background:${b[2]}"></i>${escapeHtml(b[0])}</span></div>`).join('');
  if($('#score-chart')&&typeof Chart!=='undefined'&&bands.length){
    const sum=total||1;
    new Chart($('#score-chart'),{type:'bar',data:{labels:bands.map(b=>b[0]),datasets:[{data:bands.map(b=>+b[1]||0),backgroundColor:bands.map(b=>b[2]),borderRadius:6,borderSkipped:false,barThickness:14}]},options:{indexAxis:'y',responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{displayColors:false,callbacks:{label:c=>{const n=+c.raw||0;return n+' · '+Math.round(n/sum*100)+' %'}}}},scales:{x:{beginAtZero:true,grid:{color:'rgba(255,255,255,.06)'},ticks:{color:'#71717a',font:{size:10},precision:0},border:{display:false}},y:{grid:{display:false},ticks:{color:'#e4e4e7',font:{size:11}},border:{display:false}}}}});
  }
  $('#aim-chart')?.addEventListener('click',e=>{const el=e.target.closest('[data-aim]');if(!el)return;aimPick=+el.dataset.aim;paintAim()});
  $('#aim-chart')?.addEventListener('keydown',e=>{if(e.key!=='Enter'&&e.key!==' ')return;const el=e.target.closest('[data-aim]');if(!el)return;e.preventDefault();aimPick=+el.dataset.aim;paintAim()});
  $$('[data-heat-zoom]').forEach(b=>b.onclick=()=>{heatZoom=Math.min(2.3,Math.max(1,+((heatZoom+(+b.dataset.heatZoom)).toFixed(2))));const size=500/heatZoom,o=(500-size)/2;$('#heat-board')?.setAttribute('viewBox',`${o} ${o} ${size} ${size}`)});
}

const rail=$('#app-rail');
const railToggle=$('#rail-toggle');
if(rail&&railToggle){
  let peekTimer;
  const pinnedClosed=()=>document.documentElement.dataset.rail==='closed';
  const peeking=()=>rail.classList.contains('is-peek');
  const paintRail=()=>{
    const open=!pinnedClosed()||peeking();
    railToggle.setAttribute('aria-expanded',open?'true':'false');
    railToggle.setAttribute('aria-label',open?'Sbalit menu':'Rozbalit menu');
  };
  const fitCharts=()=>{
    if(typeof Chart==='undefined')return;
    $$('#app-main canvas').forEach(node=>{
      node.style.width='100%';
      Chart.getChart(node)?.resize();
    });
  };
  const storeRail=closed=>{try{localStorage.setItem('dartiqo-rail',closed?'closed':'open')}catch{}};
  paintRail();
  rail.addEventListener('pointerenter',()=>{
    clearTimeout(peekTimer);
    if(!pinnedClosed()||document.documentElement.hasAttribute('data-rail-hold'))return;
    peekTimer=setTimeout(()=>{rail.classList.add('is-peek');paintRail()},80);
  });
  rail.addEventListener('pointerleave',()=>{
    clearTimeout(peekTimer);
    rail.classList.remove('is-peek');
    document.documentElement.removeAttribute('data-rail-hold');
    paintRail();
  });
  railToggle.onclick=()=>{
    const wasClosed=pinnedClosed();
    clearTimeout(peekTimer);
    if(!wasClosed||peeking()){
      document.documentElement.dataset.rail='closed';
      document.documentElement.dataset.railHold='';
      rail.classList.remove('is-peek');
      storeRail(true);
    }else{
      delete document.documentElement.dataset.rail;
      document.documentElement.removeAttribute('data-rail-hold');
      storeRail(false);
    }
    paintRail();
    if(wasClosed===pinnedClosed())return;
    fitCharts();
    setTimeout(fitCharts,320);
  };
}

const liveBanner=$('#live-banner');
const livePage=$('#live-page');
if(liveBanner&&typeof EventSource!=='undefined'){
  const dismissKey='dartiqo-live-dismissed';
  let current=null;
  const matchup=m=>m.players.length===2?m.players[0].name+' vs '+m.players[1].name:m.players.map(p=>p.name).join(' · ');
  const scoreline=m=>m.players.map(p=>escapeHtml(p.score)).join('<span class="px-1.5 text-zinc-600">:</span>');
  const winnerName=m=>m.winner!=null&&m.players[m.winner]?m.players[m.winner].name:null;
  const progress=m=>(m.setsToWin>1?'Set '+m.set+' · ':'')+'Leg '+m.leg;
  const dartValue=d=>{if(d==='MISS')return 0;if(d==='BULL')return 50;if(d==='25')return 25;return +d.slice(1)*({S:1,D:2,T:3}[d[0]]||1)};
  const dismissed=()=>{try{return sessionStorage.getItem(dismissKey)}catch{return null}};

  const liveHero=$('#live-hero');
  const heroArrow='<svg class="size-4 transition group-hover:translate-x-0.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg>';
  const heroLegs=(m,p,align)=>{
    const total=Math.min(m.legsToWin,7),won=Math.min(p.legs,total);
    const dots=Array.from({length:total},(_,i)=>`<i class="h-1.5 w-4 rounded-full ${i<won?'bg-accent shadow-[0_0_8px_#faff0099]':'bg-white/10'}"></i>`).join('');
    const sets=m.setsToWin>1?`<span class="text-[10px] font-semibold text-zinc-400">S${p.sets}</span>`:'';
    return `<span class="flex items-center gap-1.5 ${align==='right'?'flex-row-reverse':''}">${sets}${dots}</span>`;
  };
  const heroSide=(m,p,i,align)=>{
    const finished=m.status==='finished';
    const active=!finished&&m.active===i&&m.winner==null;
    const won=m.winner===i;
    const right=align==='right';
    const avatar=`<span class="grid size-10 shrink-0 place-items-center rounded-2xl text-sm font-bold ${won?'bg-emerald-400 text-black':active?'bg-accent text-black shadow-[0_0_24px_-4px_#faff00aa]':'bg-white/[.07] text-zinc-300'}">${escapeHtml(p.name.slice(0,1).toUpperCase())}</span>`;
    const state=won?'<span class="text-emerald-300">Vítěz</span>':active?'<span class="flex items-center gap-1.5 text-accent"><i class="size-1.5 animate-pulse rounded-full bg-accent"></i>Na tahu</span>':`<span>Ø ${p.average.toFixed(1)}</span>`;
    return `<div class="flex min-w-0 flex-col gap-3 ${right?'items-end text-right':''}">
<span class="flex max-w-full min-w-0 items-center gap-3 ${right?'flex-row-reverse':''}">${avatar}<span class="min-w-0"><strong class="block truncate text-sm font-semibold">${escapeHtml(p.name)}</strong><small class="block text-[11px] font-medium text-zinc-500">${state}</small></span></span>
<strong class="num text-6xl leading-[.85] transition-colors @2xl/dash:text-7xl @5xl/dash:text-8xl ${won?'text-emerald-300':active?'text-accent drop-shadow-[0_0_24px_#faff0055]':'text-zinc-500'}">${escapeHtml(p.score)}</strong>
${heroLegs(m,p,align)}
</div>`;
  };
  const heroRow=(m,p,i)=>{
    const finished=m.status==='finished';
    const active=!finished&&m.active===i&&m.winner==null;
    const won=m.winner===i;
    return `<div class="flex items-center gap-3 rounded-2xl px-3 py-2.5 ${active?'bg-accent/[.07] ring-1 ring-accent/30 ring-inset':won?'bg-emerald-400/10':''}">
<span class="grid size-8 shrink-0 place-items-center rounded-xl text-xs font-bold ${won?'bg-emerald-400 text-black':active?'bg-accent text-black':'bg-white/[.07] text-zinc-300'}">${escapeHtml(p.name.slice(0,1).toUpperCase())}</span>
<strong class="min-w-0 flex-1 truncate text-sm">${escapeHtml(p.name)}</strong>${heroLegs(m,p)}
<b class="num w-16 text-right text-3xl ${won?'text-emerald-300':active?'text-accent':'text-zinc-400'}">${escapeHtml(p.score)}</b>
</div>`;
  };
  const paintHero=m=>{
    if(!m){liveHero.hidden=true;liveHero.replaceChildren();return}
    const finished=m.status==='finished';
    const winner=winnerName(m);
    const duel=m.players.length===2;
    const badge=finished
      ?'<span class="inline-flex items-center gap-1.5 rounded-md bg-emerald-400 px-2 py-1 text-[10px] font-bold tracking-[.14em] text-black uppercase">Konec</span>'
      :'<span class="inline-flex items-center gap-1.5 rounded-md bg-rose-500 px-2 py-1 text-[10px] font-bold tracking-[.14em] text-white uppercase shadow-[0_0_20px_-4px_#f43f5e]"><span class="relative flex size-1.5"><i class="absolute inline-flex size-full animate-ping rounded-full bg-white opacity-80"></i><i class="relative inline-flex size-1.5 rounded-full bg-white"></i></span>Živě</span>';
    const center=duel?`<div class="flex flex-col items-center gap-2 px-1 text-center">
<span class="text-[10px] font-semibold tracking-[.18em] text-zinc-500 uppercase">${m.setsToWin>1?'Set '+m.set+' · ':''}Leg ${m.leg}</span>
<span class="num flex items-center gap-2 rounded-2xl bg-white/[.04] px-3 py-2 text-2xl ring-1 ring-white/[.06] ring-inset @2xl/dash:px-4 @2xl/dash:text-3xl">${m.players[0].legs}<i class="text-base text-zinc-600 not-italic">:</i>${m.players[1].legs}</span>
<span class="text-[10px] tracking-[.18em] text-zinc-600 uppercase">Legy</span>
</div>`:'';
    const board=duel
      ?`<div class="grid grid-cols-[minmax(0,1fr)_auto_minmax(0,1fr)] items-center gap-3 @2xl/dash:gap-8">${heroSide(m,m.players[0],0,'left')}${center}${heroSide(m,m.players[1],1,'right')}</div>`
      :`<div class="flex flex-col gap-1">${m.players.map((p,i)=>heroRow(m,p,i)).join('')}</div>`;
    const darts=m.currentDarts||[];
    const slots=[0,1,2].map(i=>darts[i]
      ?`<span class="grid h-8 min-w-11 place-items-center rounded-lg bg-accent/15 px-2 text-xs font-bold text-accent ring-1 ring-accent/30 ring-inset ${i===darts.length-1?'animate-reveal':''}">${escapeHtml(darts[i])}</span>`
      :'<span class="grid h-8 min-w-11 place-items-center rounded-lg border border-dashed border-white/10 text-xs text-zinc-600">–</span>').join('');
    const activePlayer=m.players[m.active];
    const hint=finished
      ?`<span class="text-sm text-zinc-300">${winner?`Vyhrál <b class="text-emerald-300">${escapeHtml(winner)}</b>`:'Zápas skončil'}</span>`
      :activePlayer?.checkout?`<span class="truncate text-xs text-zinc-400">Zavření <b class="font-semibold text-accent">${escapeHtml(activePlayer.checkout)}</b></span>`:'';
    const wasHidden=liveHero.hidden;
    liveHero.innerHTML=`<a class="group relative isolate block overflow-hidden rounded-[28px] border border-white/[.08] bg-zinc-900/80 shadow-[0_30px_60px_-40px_rgb(0_0_0/0.9)] transition duration-300 hover:-translate-y-0.5 hover:border-white/15 ${wasHidden?'animate-reveal':''}" href="${escapeHtml(liveHero.dataset.href)}" aria-label="${escapeHtml((finished?'Výsledek zápasu ':'Živý zápas ')+matchup(m))}">
<span class="pointer-events-none absolute inset-x-0 top-0 h-px bg-gradient-to-r from-transparent ${finished?'via-emerald-400/70':'via-rose-400/80'} to-transparent" aria-hidden="true"></span>
<span class="pointer-events-none absolute -top-32 left-1/2 -z-10 h-64 w-[36rem] -translate-x-1/2 rounded-full ${finished?'bg-emerald-400/10':'bg-rose-500/[.12]'} blur-3xl" aria-hidden="true"></span>
<span class="pointer-events-none absolute inset-0 -z-10 bg-[radial-gradient(#ffffff08_1px,transparent_1px)] [mask-image:linear-gradient(to_bottom,#000,transparent)] bg-[size:18px_18px]" aria-hidden="true"></span>
<div class="flex items-center justify-between gap-3 px-5 pt-5 sm:px-7">
<span class="flex min-w-0 items-center gap-3">${badge}<span class="truncate text-xs text-zinc-400">${escapeHtml(m.title||matchup(m))}</span></span>
<span class="hidden shrink-0 items-center gap-1.5 text-xs font-semibold text-zinc-300 group-hover:text-accent sm:flex">${finished?'Výsledek':'Sledovat živě'}${heroArrow}</span>
</div>
<div class="px-5 py-6 sm:px-7">${board}</div>
<div class="flex flex-wrap items-center justify-between gap-3 border-t border-white/[.06] bg-black/20 px-5 py-3.5 sm:px-7">
${finished?hint:`<span class="flex items-center gap-3"><span class="text-[10px] font-semibold tracking-[.16em] text-zinc-500 uppercase">${escapeHtml(activePlayer?.name||'Kolo')}</span><span class="flex gap-1.5">${slots}</span></span>${hint}`}
<span class="flex items-center gap-1.5 text-xs font-semibold text-accent sm:hidden">${finished?'Výsledek':'Sledovat'}${heroArrow}</span>
</div>
</a>`;
    liveHero.hidden=false;
  };

  const paintBanner=m=>{
    if(livePage||liveHero||!m||dismissed()===m.id+':'+m.status){liveBanner.hidden=true;return}
    const finished=m.status==='finished';
    const winner=winnerName(m);
    const detail=finished?(winner?'Vyhrál '+winner:'Zápas skončil'):progress(m)+(m.players.length>1?' · na tahu '+m.players[m.active].name:'');
    const badge=finished
      ?'<span class="chip bg-emerald-400/15 text-emerald-300 ring-1 ring-emerald-400/30 ring-inset">Konec zápasu</span>'
      :'<span class="chip bg-rose-500/15 text-rose-300 ring-1 ring-rose-400/30 ring-inset"><i class="size-1.5 animate-pulse rounded-full bg-rose-400"></i>Živě z mobilu</span>';
    const wasHidden=liveBanner.hidden;
    liveBanner.innerHTML=`<div class="panel border-white/15! bg-zinc-900/95! p-4! shadow-[0_30px_60px_-20px_rgb(0_0_0/0.8)]! backdrop-blur-xl sm:p-5! ${wasHidden?'animate-reveal':''}">
<div class="flex items-center justify-between gap-3">${badge}<button class="icon-btn size-8" type="button" data-live-dismiss aria-label="Skrýt">×</button></div>
<div class="mt-3 flex items-center gap-4"><span class="min-w-0 flex-1"><strong class="block truncate text-sm">${escapeHtml(matchup(m))}</strong><small class="block truncate text-xs text-zinc-400">${escapeHtml(m.title||'')}</small><small class="block truncate text-xs text-zinc-500">${escapeHtml(detail)}</small></span><span class="num shrink-0 text-3xl leading-none">${scoreline(m)}</span></div>
<a class="btn-primary mt-4 h-10! w-full" href="${escapeHtml(url('/app/live'))}">${finished?'Zobrazit výsledek':'Sledovat na obrazovce'}</a>
</div>`;
    liveBanner.hidden=false;
    $('[data-live-dismiss]',liveBanner).onclick=()=>{try{sessionStorage.setItem(dismissKey,m.id+':'+m.status)}catch{}liveBanner.hidden=true};
  };

  // Barvy zápasové obrazovky z iOS aplikace (MatchColors, Theme.playerColors)
  const MC={coral:'#ff5233',amber:'#ff991a',ink:'#0b1a13',green:'#21cc7d',red:'#ff453a',positive:'#4dd984',bull:'#ff9f0a'};
  const playerColors=['#fefc03','#59c7ff','#ff8c40','#f273d9'];
  const playerColor=i=>playerColors[i%playerColors.length];
  const onTurn=(m,i)=>m.status==='live'&&m.winner==null&&m.active===i;
  const cpuIcon='<svg class="size-3 shrink-0" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" aria-hidden="true"><rect x="6" y="6" width="12" height="12" rx="2"/><path d="M10 2v4M14 2v4M10 18v4M14 18v4M2 10h4M2 14h4M18 10h4M18 14h4"/></svg>';
  const dartColor=d=>d==='MISS'?null:d==='BULL'||d==='25'?MC.bull:d[0]==='T'?MC.red:d[0]==='D'?MC.positive:'#ffffff';

  // Velikosti rostou s výškou okna, aby šel zápas číst i z dálky na monitoru nebo televizi
  const progressStrip=m=>{
    const finished=m.status==='finished';
    const darts=(m.currentDarts||[]).length;
    const caption=finished?(winnerName(m)?'Vyhrál '+winnerName(m):'Zápas skončil'):(m.setsToWin>1?'Set '+m.set+' · ':'')+'Leg '+m.leg+' · Šipky '+darts+'/3';
    const tint=i=>m.players.length<=2?(onTurn(m,i)?MC.coral:MC.amber):playerColor(i);
    const divider='<i class="mx-[.6em] h-[1.2em] w-px shrink-0 bg-white/20" aria-hidden="true"></i>';
    const score=(title,values,total)=>`${divider}<span class="flex min-w-0 flex-1 items-center justify-center gap-[.4em] whitespace-nowrap"><span class="font-semibold text-white/80">${title}</span><span class="flex items-center gap-[.3em] text-[1.3em] font-extrabold tabular-nums">${values.map((v,i)=>`${i?'<span class="text-white/40">:</span>':''}<span style="color:${tint(i)}">${v}</span>`).join('')}</span><span class="text-[.9em] font-semibold text-white/40 tabular-nums">(do ${total})</span></span>`;
    return `<div class="match-glass flex min-h-[2.8em] items-center rounded-[14px] px-[.6em] py-[.4em] text-[clamp(13px,1.8vh,28px)] 2xl:rounded-[20px]"><span class="min-w-0 flex-1 truncate text-center font-semibold text-white/80 tabular-nums">${escapeHtml(caption)}</span>${m.setsToWin>1?score('Sety',m.players.map(p=>p.sets),m.setsToWin):''}${m.setsToWin>1||m.legsToWin>1?score('Legy',m.players.map(p=>p.legs),m.legsToWin):''}</div>`;
  };

  const panelChips=(m,p,i)=>{
    const stat=m.mode==='cricket'?['Zavřeno',m.numbers.filter(n=>(p.marks[n]||0)>=3).length+'/'+m.numbers.length]
      :m.mode==='aroundClock'?['Hotovo',(p.score==='Bull'?20:Math.max(0,+p.score-1))+'/21']
      :['Ø',p.darts?p.average.toFixed(1):'—'];
    const won=m.winner===i?`<span class="inline-flex items-center rounded-full px-[.7em] py-[.25em] text-[.8em] font-extrabold uppercase" style="background:${MC.ink};color:${MC.green}">Vítěz</span>`:'';
    return won+`<span class="inline-flex items-center gap-[.3em] rounded-full px-[.7em] py-[.25em]" style="background:${MC.ink}1f"><span class="text-[.8em] font-extrabold opacity-60">${stat[0]}</span><b class="font-bold tabular-nums">${stat[1]}</b></span>`;
  };

  // Karty se staví jen jednou na zápas, pak se mění jen hodnoty, aby mohly běžet animace
  const buildPanels=(grid,m,cols,rows)=>{
    // Skóre se řídí velikostí scoreboardu (cqw/cqh), ne celého okna
    const base=`clamp(14px,min(${cols===2?1.9:2.6}cqw,${(5/rows).toFixed(2)}cqh),44px)`;
    const big=`min(${cols===2?19:30}cqw,${(54/rows).toFixed(1)}cqh)`;
    grid.className='relative grid flex-1 auto-rows-fr overflow-hidden rounded-[22px] 2xl:rounded-[32px] '+(cols===2?'grid-cols-2':'grid-cols-1');
    grid.style.background=MC.amber;
    grid.innerHTML='<i class="pointer-events-none absolute top-0 left-0 z-0 transition-[transform,width,height,background-color] duration-500 ease-[cubic-bezier(.65,0,.35,1)]" data-focus aria-hidden="true"></i>'
      +m.players.map((p,i)=>`<article class="relative z-[1] flex min-h-0 min-w-0 flex-col p-[1em]" style="color:${MC.ink};font-size:${base}" data-i="${i}">
<div class="flex min-w-0 items-center gap-[.45em]"><span class="grid size-[1.6em] shrink-0 place-items-center rounded-full text-[.7em] font-bold" style="background:${MC.ink}26">${escapeHtml(p.name.slice(0,1).toUpperCase())}</span><strong class="min-w-0 flex-1 truncate font-semibold">${escapeHtml(p.name)}</strong>${p.bot?cpuIcon.replace('size-3','size-[1em]'):''}</div>
<strong class="flex min-h-0 flex-1 items-center leading-none font-bold tracking-tight tabular-nums transition-colors duration-500" style="font-size:${big}" data-score></strong>
<div class="flex flex-wrap gap-[.3em]" data-chips></div>
</article>`).join('');
  };

  const placeFocus=(grid,focus,color,instant)=>{
    const ind=$('[data-focus]',grid),panel=grid.querySelector(`article[data-i="${focus}"]`);
    if(!ind)return;
    ind.hidden=!panel;
    if(!panel)return;
    if(instant)ind.style.transition='none';
    Object.assign(ind.style,{width:panel.offsetWidth+'px',height:panel.offsetHeight+'px',transform:`translate(${panel.offsetLeft}px,${panel.offsetTop}px)`,background:color});
    if(instant){ind.offsetWidth;ind.style.transition=''}
  };

  // Skóre se k nové hodnotě dopočítá, místo aby skočilo
  const countTo=(el,text)=>{
    const prev=el.dataset.value;
    el.dataset.value=text;
    cancelAnimationFrame(el._raf);
    if(reduced||prev===undefined||prev===text||!/^\d+$/.test(prev)||!/^\d+$/.test(text)){el.textContent=text;return}
    const from=+prev,to=+text,start=performance.now(),duration=Math.min(1100,400+Math.abs(to-from)*5);
    const step=now=>{
      const t=Math.min(1,(now-start)/duration);
      el.textContent=Math.round(from+(to-from)*(1-Math.pow(1-t,3)));
      if(t<1)el._raf=requestAnimationFrame(step);
    };
    el._raf=requestAnimationFrame(step);
  };

  const paintPlayers=m=>{
    const grid=$('#live-players');
    const cols=Math.min(2,m.players.length),rows=Math.ceil(m.players.length/cols);
    const key=[m.id,cols,...m.players.map(p=>p.name)].join('|');
    const fresh=grid.dataset.key!==key;
    if(fresh){buildPanels(grid,m,cols,rows);grid.dataset.key=key}
    m.players.forEach((p,i)=>{
      const panel=grid.querySelector(`article[data-i="${i}"]`);
      const active=onTurn(m,i);
      panel.setAttribute('aria-current',active?'true':'false');
      const score=$('[data-score]',panel);
      score.style.color=active?'#fff':MC.ink;
      countTo(score,String(p.score));
      $('[data-chips]',panel).innerHTML=panelChips(m,p,i);
    });
    const focus=m.winner??m.active;
    grid._focus=[focus,m.winner!=null?MC.green:MC.coral];
    placeFocus(grid,...grid._focus,fresh);
    if(!grid._ro&&typeof ResizeObserver!=='undefined'){
      grid._ro=new ResizeObserver(()=>grid._focus&&placeFocus(grid,...grid._focus,true));
      grid._ro.observe(grid);
    }
    const notch=$('#live-notch');
    notch.hidden=focus==null||!m.players[focus];
    if(!notch.hidden)notch.style.left=((focus%cols)+.5)/cols*100+'%';
  };

  const throwSlot=(i,dart,tip,fresh)=>{
    if(dart)return `<div class="flex flex-1 flex-col items-center justify-center gap-[.15em] ${fresh?'animate-reveal':''}"><span class="text-[.6em] font-bold text-white/45">${i+1}</span><b class="text-[1.9em] leading-none font-bold tabular-nums">${dartValue(dart)}</b><span class="text-[.8em] font-bold text-white/70">${escapeHtml(dart)}</span></div>`;
    if(tip)return `<div class="flex flex-1 flex-col items-center justify-center gap-[.15em]" style="color:${MC.green}"><span class="flex items-center gap-[.25em] text-[.6em] font-extrabold opacity-70"><svg class="size-[.9em]" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2l2.4 7.6L22 12l-7.6 2.4L12 22l-2.4-7.6L2 12l7.6-2.4z"/></svg>AI</span><b class="text-[1.9em] leading-none font-extrabold">${escapeHtml(tip)}</b><span class="text-[.8em] font-bold tabular-nums opacity-75">${dartValue(tip)}</span></div>`;
    return `<div class="flex flex-1 flex-col items-center justify-center gap-[.15em]"><span class="text-[.6em] font-bold text-white/40">${i+1}</span><b class="text-[1.9em] leading-none font-bold text-white/30">—</b><span class="text-[.8em] font-semibold text-white/50">${i+1}. šipka</span></div>`;
  };

  const throwStrip=m=>{
    const darts=m.currentDarts||[];
    const player=m.players[m.active];
    const route=m.status==='live'&&m.mode==='x01'&&player?.checkout?player.checkout.split(' '):[];
    const slots=[0,1,2].map(i=>(i?'<i class="my-auto h-[2.6em] w-px shrink-0 bg-white/20" aria-hidden="true"></i>':'')+throwSlot(i,darts[i],darts[i]?null:route[i-darts.length],i===darts.length-1)).join('');
    return `<div class="match-glass flex h-[7.5em] items-stretch gap-[.4em] rounded-[14px] px-[.6em] py-[.4em] text-[clamp(16px,2.9vh,46px)] 2xl:rounded-[20px]" aria-label="Aktuální hod">${slots}</div>`;
  };

  const cricketCard=m=>{
    const symbol=n=>['—','/','×','⊗'][Math.min(3,Math.max(0,n))];
    const head=`<tr><th class="w-[4em]"></th>${m.numbers.map(n=>`<th class="px-[.3em] pb-[.4em] text-[.8em] font-bold" style="color:${MC.ink}73">${n===25?'B':n}</th>`).join('')}</tr>`;
    const rows=m.players.map((p,i)=>`<tr><td class="max-w-[4em] truncate pr-[.5em] text-left text-[.75em] font-bold" style="color:${onTurn(m,i)?MC.coral:MC.ink+'b3'}">${escapeHtml(p.name)}</td>${m.numbers.map(n=>{const k=p.marks[n]||0;return `<td class="h-[1.7em] px-[.3em] text-center font-bold" style="color:${k>=3?MC.green:MC.ink+'b8'}">${symbol(k)}</td>`}).join('')}</tr>`).join('');
    return `<div class="overflow-x-auto rounded-[22px] bg-[#fff] px-[.8em] py-[.6em] text-[clamp(15px,2.1vh,34px)]"><table class="w-full border-collapse text-center">${head}${rows}</table></div>`;
  };


  // Jedna řádka = jedno kolo. Chronologicky od začátku dolů.
  const visitRow=(m,v,open,n)=>{
    const name=m.players[v.player]?.name||'';
    const tint=playerColor(v.player);
    const total=v.darts.reduce((s,d)=>s+dartValue(d),0);
    const score=open?total:v.bust?null:v.score;
    const scoreColor=v.bust||score===180?MC.red:v.checkout?MC.positive:open?'#fefc03':'#fff';
    const marks=v.darts.length
      ?v.darts.map(d=>{const c=dartColor(d)||'#ffffffaa';return `<span class="font-bold tabular-nums" style="color:${c}">${d==='MISS'?'–':escapeHtml(d)}</span>`}).join('<span class="text-white/20">·</span>')
      :'<span class="text-white/30">—</span>';
    const note=v.bust?'Přehoz':v.checkout?'Zavřeno':open?'Hází':'';
    return `<div class="grid shrink-0 grid-cols-[minmax(0,1.1fr)_minmax(0,1.6fr)_auto] items-center gap-x-2 rounded-xl px-1.5 py-2 text-[clamp(13px,1.55vh,22px)] ${open?'bg-[#fefc03]/18 ring-1 ring-[#fefc03]/35 ring-inset':v.bust?'bg-[#ff453a]/12':v.checkout?'bg-[#4dd984]/12':n%2?'bg-white/[.03]':''}">
<span class="flex min-w-0 items-center gap-1.5"><i class="size-2 shrink-0 rounded-full" style="background:${tint}" aria-hidden="true"></i><strong class="truncate font-semibold">${escapeHtml(name)}</strong>${open?'<span class="shrink-0 rounded bg-[#fefc03] px-1 py-px text-[9px] font-extrabold tracking-wide text-black uppercase">teď</span>':''}</span>
<span class="flex min-w-0 flex-wrap items-center gap-x-1.5 gap-y-0.5 leading-none">${marks}${note&&!open?`<span class="text-[.65em] font-semibold text-white/40">${note}</span>`:''}</span>
<span class="text-right leading-none"><b class="text-[1.35em] font-extrabold tabular-nums" style="color:${scoreColor}">${score==null?'BUST':score}</b></span>
</div>`;
  };

  const legHeader=(m,leg,set,live)=>{
    const playsSets=m.setsToWin>1;
    const title=playsSets?`Set ${set} · Leg ${leg}`:`Leg ${leg}`;
    return `<div class="mt-2 flex shrink-0 items-center gap-2 first:mt-0"><span class="text-[11px] font-extrabold tracking-[.14em] text-white/55 uppercase 2xl:text-xs">${title}</span>${live?'<span class="rounded bg-white/15 px-1.5 py-0.5 text-[9px] font-extrabold tracking-wide text-white/80 uppercase">teď</span>':''}<i class="h-px flex-1 bg-white/10" aria-hidden="true"></i></div>`;
  };

  // Když telefon ještě neposílá leg u kola, odhadneme ho podle zavření
  const withLegs=(m,list)=>{
    let leg=1,set=1,setLegs=m.players.map(()=>0);
    return list.map(v=>{
      if(v.leg!=null)return {...v,leg:+v.leg,set:+(v.set||1)};
      const row={...v,leg,set};
      if(v.checkout&&!v.bust){
        setLegs[v.player]=(setLegs[v.player]||0)+1;
        leg+=1;
        if(m.setsToWin>1&&setLegs[v.player]>=m.legsToWin){set+=1;setLegs=m.players.map(()=>0)}
      }
      return row;
    });
  };

  const visitLog=(m,finished)=>{
    const open=!finished&&(m.currentDarts||[]).length;
    const rows=withLegs(m,m.visits||[]);
    if(open)rows.push({player:m.active,darts:m.currentDarts,leg:m.leg,set:m.set||1,_open:true});
    if(!rows.length)return '<span class="block py-6 text-center text-sm text-white/50">Zatím nepadla žádná šipka.</span>';
    let html='',prev='',n=0;
    for(const v of rows){
      const key=`${v.set||1}:${v.leg||1}`;
      if(key!==prev){
        html+=legHeader(m,v.leg||1,v.set||1,!finished&&(v.leg||1)===m.leg&&(v.set||1)===(m.set||1));
        prev=key;n=0;
      }
      html+=visitRow(m,v,!!v._open,n++);
    }
    return html;
  };

  const paintBadge=m=>{
    const badge=$('#live-badge');
    const base='inline-flex shrink-0 items-center gap-1.5 rounded-full px-2.5 py-1 text-[10px] font-bold tracking-wider uppercase 2xl:text-xs ';
    if(!m){badge.className=base+'bg-white/10 text-white/60';badge.textContent='Bez zápasu';return}
    const finished=m.status==='finished';
    badge.className=base+(finished?'bg-[#21cc7d] text-[#0b1a13]':'bg-[#ff5233] text-white');
    badge.innerHTML=finished?'Konec':'<i class="size-1.5 animate-pulse rounded-full bg-white"></i>Živě';
  };

  const paintPage=m=>{
    const board=$('#live-board'),empty=$('#live-empty');
    paintBadge(m);
    if(!m){
      board.hidden=true;empty.hidden=false;$("#live-players").dataset.key="";
      $('#live-meta').textContent='';$('#live-title').textContent='Živý zápas';
      return;
    }
    const finished=m.status==='finished';
    board.hidden=false;empty.hidden=true;
    const started=new Date(m.startedAt);
    $('#live-meta').textContent=[m.title,progress(m),'začátek '+started.toLocaleTimeString('cs-CZ',{hour:'2-digit',minute:'2-digit'})].filter(Boolean).join(' · ');
    $('#live-title').textContent=matchup(m);
    $('#live-progress').innerHTML=progressStrip(m);
    paintPlayers(m);
    $('#live-strip').innerHTML=(m.mode==='cricket'&&m.numbers.length?cricketCard(m):'')+(finished?'':throwStrip(m));
    const box=$('#live-visits');
    box.innerHTML=visitLog(m,finished);
    box.scrollTop=box.scrollHeight;
  };

  let watchedLive=false,reloadQueued=false;
  const paint=m=>{
    current=m;paintBanner(m);if(livePage)paintPage(m);
    if(!liveHero)return;
    const finished=m?.status==='finished';
    // Dohraný zápas už je v Posledních hrách, výsledek ukážeme jen při sledování konce
    if(finished&&!watchedLive){paintHero(null);return}
    if(m&&!finished)watchedLive=true;
    paintHero(m);
    if(finished&&!reloadQueued&&liveHero.hasAttribute('data-reload-on-finish')){reloadQueued=true;setTimeout(()=>location.reload(),6000)}
  };
  const source=new EventSource(liveBanner.dataset.stream);
  source.onmessage=e=>{try{paint(JSON.parse(e.data).match||null)}catch{}};
  if(livePage){
    source.onopen=()=>paintBadge(current);
    source.onerror=()=>{const badge=$('#live-badge');badge.className='inline-flex shrink-0 items-center gap-1.5 rounded-full bg-white/10 px-2.5 py-1 text-[10px] font-bold tracking-wider text-white/60 uppercase 2xl:text-xs';badge.textContent='Obnovuji spojení…'};
    const fs=$('[data-live-fullscreen]'),page=document.documentElement;
    if(fs&&page.requestFullscreen){
      fs.onclick=()=>document.fullscreenElement?document.exitFullscreen():page.requestFullscreen().catch(()=>{});
      document.addEventListener('fullscreenchange',()=>{
        const on=!!document.fullscreenElement;
        $('[data-live-fullscreen-label]',fs).textContent=on?'Ukončit':'Celá obrazovka';
        fs.title=on?'Ukončit celou obrazovku':'Celá obrazovka';
      });
    }else if(fs)fs.hidden=true;
  }
}
